import math,re,sys
PALETTE=' .:-=+*#%@'  # maybe include space
# actual glyph formula below uses low palette no bg
GLYPHS=' .:-=+*#%@'

def load_stl(path):
    tris=[]; cur=[]
    for line in open(path):
        parts=line.strip().split()
        if len(parts)>=4 and parts[0]=='vertex':
            cur.append(tuple(map(float,parts[1:4])))
            if len(cur)==3:
                tris.append((cur[0],cur[1],cur[2],(255,255,0)))
                cur=[]
    return tris

def rotate(p,x=0,y=0,z=0):
    px,py,pz=p
    if x:
        c=math.cos(x); s=math.sin(x); py,pz=py*c-pz*s, py*s+pz*c
    if y:
        c=math.cos(y); s=math.sin(y); px,pz=px*c+pz*s, -px*s+pz*c
    if z:
        c=math.cos(z); s=math.sin(z); px,py=px*c-py*s, px*s+py*c
    return (px,py,pz)

def normal(a,b,c):
    ux,uy,uz=b[0]-a[0],b[1]-a[1],b[2]-a[2]
    vx,vy,vz=c[0]-a[0],c[1]-a[1],c[2]-a[2]
    nx=uy*vz-uz*vy; ny=uz*vx-ux*vz; nz=ux*vy-uy*vx
    l=math.sqrt(nx*nx+ny*ny+nz*nz)
    return (nx/l,ny/l,nz/l) if l else (0,0,1)

def glyph(nz):
    v=abs(nz)
    idx=int(math.floor(v*10))-1
    if idx<0: idx=0
    if idx>8: idx=8
    return '.:-=+*#%@'[idx]

def render(path,w,h,x=0,y=0,z=0):
    tris=load_stl(path)
    rtris=[]; maxabs=0
    for a,b,c,col in tris:
        ra,rb,rc=rotate(a,x,y,z),rotate(b,x,y,z),rotate(c,x,y,z)
        rtris.append((ra,rb,rc,col))
        for p in (ra,rb,rc):
            maxabs=max(maxabs,abs(p[0]),abs(p[1]),abs(p[2]))
    if maxabs==0: maxabs=1
    W=w; H=h; L=(w+1)*h
    chars=[' ']*L; zbuf=[-1e99]*L
    def proj(p):
        sx=(1-p[0]/maxabs)*w/2.0
        sy=(1-p[1]/maxabs)*h/2.0
        # depth maybe pz/max
        return sx,sy,p[2]/maxabs
    for a,b,c,col in rtris:
        pa,pb,pc=proj(a),proj(b),proj(c)
        n=normal(a,b,c); ch=glyph(n[2])
        xs=[pa[0],pb[0],pc[0]]; ys=[pa[1],pb[1],pc[1]]
        minx=max(0,math.floor(min(xs))); maxx=min(w-1,math.ceil(max(xs)))
        miny=max(0,math.floor(min(ys))); maxy=min(h-1,math.ceil(max(ys)))
        # barycentric
        x1,y1,z1=pa; x2,y2,z2=pb; x3,y3,z3=pc
        den=(y2-y3)*(x1-x3)+(x3-x2)*(y1-y3)
        if abs(den)<1e-9: continue
        for iy in range(miny,maxy+1):
            # newline sentinel if row has raster? set at index iy*w+1
            # set after draw? We'll set if any pixel row maybe later
            for ix in range(minx,maxx+1):
                px=ix; py=iy
                l1=((y2-y3)*(px-x3)+(x3-x2)*(py-y3))/den
                l2=((y3-y1)*(px-x3)+(x1-x3)*(py-y3))/den
                l3=1-l1-l2
                if l1>=0 and l2>=0 and l3>=0:
                    idx=iy*w+ix
                    if 0<=idx<L:
                        zz=l1*z1+l2*z2+l3*z3
                        if zz>=zbuf[idx]:
                            zbuf[idx]=zz; chars[idx]=ch
    # set newlines at x=1 for rows containing non-space in row width w
    for iy in range(h):
        row=chars[iy*w:(iy+1)*w]
        if any(c!=' ' for c in row):
            idx=iy*w+1
            if 0<=idx<L and chars[idx]==' ':
                chars[idx]='\n'
    return ''.join(chars)

if __name__=='__main__':
    print(render(sys.argv[1],int(sys.argv[2]),int(sys.argv[3])),end='')
