#!/usr/bin/env python3
"""A small command-line 3D renderer compatible with the observed sloth executable."""
import math
import os
import sys
from dataclasses import dataclass
from typing import Dict, List, Optional, Sequence, Tuple

VERSION = "Sloth 0.1"
BG = (25, 25, 25)
BLACK = (0, 0, 0)
YELLOW = (255, 255, 0)
GLYPHS = ".:-=+*#%@"

