            if a.startswith("-h="):
                p.height = a.split("=", 1)[1]; i += 1
            elif i + 1 < len(argv) and not argv[i + 1].startswith('-'):
                p.height = argv[i + 1]; i += 2
            else:
                return None, clap_error("The argument '-h <height>' requires a value but none was supplied", "executable image [FLAGS] [OPTIONS] -w <width>")
            continue
        if in_image and (a in ("-j", "--webify") or a.startswith("-j=") or a.startswith("--webify=")):
            if a.startswith("-j=") or a.startswith("--webify="):
                p.webify = a.split("=", 1)[1]; i += 1
            elif i + 1 < len(argv) and not argv[i + 1].startswith('-'):
                p.webify = argv[i + 1]; i += 2
            else:
                return None, clap_error("The argument '-j, --webify <frame count>' requires a value but none was supplied", "executable image [FLAGS] [OPTIONS] -w <width>")
            continue
        if a.startswith('-'):
            usage = "executable image [FLAGS] [OPTIONS] -w <width>" if in_image else "executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]"
            return None, clap_error(f"Found argument '{a}' which wasn't expected, or isn't valid in this context", usage)
        if in_image:
            return None, clap_error(f"Found argument '{a}' which wasn't expected, or isn't valid in this context", "executable <input filename(s)>... image -h <height> -w <width>")
        p.input_args.append(a)
        i += 1

    if not p.input_args:
        return None, clap_error("The following required arguments were not provided:\n    <input filename(s)>...", "executable [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]")
    if p.image and p.width is None:
        return None, clap_error("The following required arguments were not provided:\n    -w <width>", "executable image [FLAGS] [OPTIONS] -w <width>")
    return p, None


def parse_int_observed(s: str):
    try:
        return int(s)
    except Exception:
        eprint("Error: ParseIntError { kind: InvalidDigit }\n")
        return None


def parse_float_observed(s: str):
    try:
        return float(s)
    except Exception:
        eprint("Error: ParseFloatError { kind: Invalid }\n")
        return None


def main(argv: List[str]) -> int:
    parsed, err = parse_cli(argv)
    if parsed == "exit":
        return int(err)
    if err is not None:
        return int(err)
    assert isinstance(parsed, Parsed)

    # Load inputs before terminal setup, matching panics for bad OBJ/materials.
    try:
        tris = load_inputs(parsed.input_args)
    except RuntimeError as e:
        msg = str(e)
        if msg.startswith("Expected to have materials"):
            return panic("src/inputs.rs:112:39", msg)
        return panic("src/inputs.rs:126:39", f"called `Result::unwrap()` on an `Err` value: \"{msg}\"")

    if parsed.image:
        width = parse_int_observed(parsed.width or "")
        if width is None:
            return 1
        height = parse_int_observed(parsed.height) if parsed.height is not None else width
        if height is None:
            return 1
        xr = parse_float_observed(parsed.ix)
        yr = parse_float_observed(parsed.iy)
        zr = parse_float_observed(parsed.iz)
        if xr is None or yr is None or zr is None:
            return 1
        if parsed.webify is not None:
            frames = parse_int_observed(parsed.webify)
            if frames is None:
                return 1
            try:
                sys.stdout.write(webify_output(tris, width, height, frames, xr, yr, zr))
            except IndexError as e:
                return panic("src/rasterizer.rs:90:33", str(e))
            return 0
        try:
            chars, colors = render_triangles(tris, width, height, xr, yr, zr)
        except IndexError as e:
            return panic("src/rasterizer.rs:90:33", str(e))
        if parsed.bw:
            sys.stdout.write(plain_output(chars))
        else:
            sys.stdout.write(ansi_output(chars, colors))
        return 0

    # Interactive mode: when stdout is not a terminal, the original failed while
    # querying terminal size via ioctl.
    if not sys.stdout.isatty():
        eprint('Error: IoError(Os { code: 25, kind: Uncategorized, message: "Inappropriate ioctl for device" })\n')
        return 1
    try:
        cols, rows = os.get_terminal_size(sys.stdout.fileno())
    except OSError:
        eprint('Error: IoError(Os { code: 25, kind: Uncategorized, message: "Inappropriate ioctl for device" })\n')
        return 1
    xr = parse_float_observed(parsed.global_ix); yr = parse_float_observed(parsed.global_iy); zr = parse_float_observed(parsed.global_iz)
    if xr is None or yr is None or zr is None:
        return 1
    # A simple single-frame terminal render is sufficient for direct TTY use.
    chars, colors = render_triangles(tris, max(1, cols - 1), max(1, rows - 1), xr, yr, zr)
    if parsed.bw:
        sys.stdout.write(plain_output(chars))
    else:
        sys.stdout.write(ansi_output(chars, colors))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
